css:
svg.lucide { stroke-width: 1.75; }
::selection { background: rgba(139,156,255,.32); }

/* Chat backdrop: aurora night scene. Dark only behind the reading column, edges left bright */
.dark [data-workspace-area="conversation"] {
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(ellipse 40% 85% at 50% 42%, rgba(8,10,15,.82) 0%, rgba(8,10,15,.74) 58%, rgba(8,10,15,.30) 100%),
    linear-gradient(180deg, rgba(8,10,15,.25) 0%, rgba(8,10,15,0) 30%, rgba(8,10,15,0) 80%, rgba(8,10,15,.15) 100%),
    var(--theme-background-image) center bottom / cover no-repeat,
    #0a0c11 !important;
}
:root:not(.dark) [data-workspace-area="conversation"] {
  background:
    radial-gradient(1100px 520px at 88% -8%, rgba(79,91,213,.07), transparent 62%),
    #f7f6f3 !important;
}
.dark .messages-timeline-scroll { background: transparent !important; }

/* Twinkling stars at the edges */
.dark [data-workspace-area="conversation"]::before {
  content: "" !important;
  position: absolute !important; inset: 0 !important; z-index: -1 !important; pointer-events: none !important;
  display: block !important;
  background: radial-gradient(circle at 89.2% 28.8%, rgba(255,255,255,.95) 0 1.5px, rgba(190,205,255,.35) 2.3px, transparent 4.1px),radial-gradient(circle at 94.1% 38.9%, rgba(255,255,255,.95) 0 1.5px, rgba(190,205,255,.35) 2.3px, transparent 4.1px),radial-gradient(circle at 3.9% 33.7%, rgba(255,255,255,.95) 0 1.5px, rgba(190,205,255,.35) 2.3px, transparent 4.1px),radial-gradient(circle at 89.9% 58.0%, rgba(255,255,255,.95) 0 1.4px, rgba(190,205,255,.35) 2.2px, transparent 4.0px),radial-gradient(circle at 14.3% 50.4%, rgba(255,255,255,.95) 0 1.0px, rgba(190,205,255,.35) 1.8px, transparent 3.6px),radial-gradient(circle at 2.7% 47.4%, rgba(255,255,255,.95) 0 1.2px, rgba(190,205,255,.35) 2.0px, transparent 3.8px),radial-gradient(circle at 13.8% 39.5%, rgba(255,255,255,.95) 0 1.3px, rgba(190,205,255,.35) 2.1px, transparent 3.9px),radial-gradient(circle at 87.1% 26.2%, rgba(255,255,255,.95) 0 1.3px, rgba(190,205,255,.35) 2.1px, transparent 3.9px),radial-gradient(circle at 79.7% 21.0%, rgba(255,255,255,.95) 0 1.1px, rgba(190,205,255,.35) 1.9px, transparent 3.7px),radial-gradient(circle at 7.8% 25.8%, rgba(255,255,255,.95) 0 1.5px, rgba(190,205,255,.35) 2.3px, transparent 4.1px),radial-gradient(circle at 9.7% 15.2%, rgba(255,255,255,.95) 0 1.6px, rgba(190,205,255,.35) 2.4px, transparent 4.2px),radial-gradient(circle at 85.5% 26.9%, rgba(255,255,255,.95) 0 1.3px, rgba(190,205,255,.35) 2.1px, transparent 3.9px),radial-gradient(circle at 91.5% 8.0%, rgba(255,255,255,.95) 0 1.2px, rgba(190,205,255,.35) 2.0px, transparent 3.8px),radial-gradient(circle at 21.3% 10.7%, rgba(255,255,255,.95) 0 1.4px, rgba(190,205,255,.35) 2.2px, transparent 4.0px),radial-gradient(circle at 87.3% 13.1%, rgba(255,255,255,.95) 0 1.3px, rgba(190,205,255,.35) 2.1px, transparent 3.9px),radial-gradient(circle at 10.9% 26.9%, rgba(255,255,255,.95) 0 1.2px, rgba(190,205,255,.35) 2.0px, transparent 3.8px),radial-gradient(circle at 9.9% 18.4%, rgba(255,255,255,.95) 0 1.6px, rgba(190,205,255,.35) 2.4px, transparent 4.2px),radial-gradient(circle at 18.1% 15.0%, rgba(255,255,255,.95) 0 1.2px, rgba(190,205,255,.35) 2.0px, transparent 3.8px),radial-gradient(circle at 19.1% 5.4%, rgba(255,255,255,.95) 0 1.1px, rgba(190,205,255,.35) 1.9px, transparent 3.7px),radial-gradient(circle at 78.2% 50.3%, rgba(255,255,255,.95) 0 1.2px, rgba(190,205,255,.35) 2.0px, transparent 3.8px),radial-gradient(circle at 3.5% 3.9%, rgba(255,255,255,.95) 0 1.2px, rgba(190,205,255,.35) 2.0px, transparent 3.8px),radial-gradient(circle at 80.5% 50.4%, rgba(255,255,255,.95) 0 1.1px, rgba(190,205,255,.35) 1.9px, transparent 3.7px),radial-gradient(circle at 90.5% 54.8%, rgba(255,255,255,.95) 0 1.5px, rgba(190,205,255,.35) 2.3px, transparent 4.1px),radial-gradient(circle at 7.0% 42.2%, rgba(255,255,255,.95) 0 1.2px, rgba(190,205,255,.35) 2.0px, transparent 3.8px),radial-gradient(circle at 11.7% 8.9%, rgba(255,255,255,.95) 0 1.0px, rgba(190,205,255,.35) 1.8px, transparent 3.6px),radial-gradient(circle at 82.8% 17.6%, rgba(255,255,255,.95) 0 1.5px, rgba(190,205,255,.35) 2.3px, transparent 4.1px) !important;
  animation: nf-twinkle 3.8s ease-in-out infinite !important;
}
/* Aurora glow drifting and shifting hue, kept mostly off the reading column */
.dark [data-workspace-area="conversation"]::after {
  content: "" !important;
  position: absolute !important; inset: 0 !important; z-index: -1 !important; pointer-events: none !important;
  display: block !important;
  background:
    radial-gradient(22% 18% at 15% 44%, rgba(94,234,212,.24), transparent 72%),
    radial-gradient(20% 16% at 40% 36%, rgba(192,132,252,.16), transparent 72%),
    radial-gradient(24% 18% at 65% 46%, rgba(94,234,212,.18), transparent 72%),
    radial-gradient(22% 18% at 88% 38%, rgba(139,156,255,.24), transparent 72%) !important;
  background-size: 200% 100% !important;
  background-repeat: repeat-x !important;
  mix-blend-mode: screen;
  -webkit-mask-image: linear-gradient(90deg, #000 0%, #000 20%, rgba(0,0,0,.2) 36%, rgba(0,0,0,.2) 64%, #000 80%, #000 100%);
  mask-image: linear-gradient(90deg, #000 0%, #000 20%, rgba(0,0,0,.2) 36%, rgba(0,0,0,.2) 64%, #000 80%, #000 100%);
  animation: nf-aurora 28s ease-in-out infinite alternate, nf-hue 17s ease-in-out infinite alternate !important;
}
@keyframes nf-twinkle { 0% { opacity: .2; } 18% { opacity: 1; } 34% { opacity: .45; } 52% { opacity: .9; } 70% { opacity: .15; } 86% { opacity: .8; } 100% { opacity: .2; } }
@keyframes nf-aurora { 0% { background-position: 0% 0%; opacity: .55; } 50% { opacity: 1; } 100% { background-position: 100% 0%; opacity: .65; } }
@keyframes nf-hue { 0% { filter: hue-rotate(0deg); } 100% { filter: hue-rotate(38deg); } }
@media (prefers-reduced-motion: reduce) {
  .dark [data-workspace-area="conversation"]::before, .dark [data-workspace-area="conversation"]::after { animation: none !important; }
}

/* Glass header with an aurora edge */
.dark [data-chat-header] {
  background: rgba(10,12,17,.55) !important;
  backdrop-filter: blur(14px) saturate(140%);
  border-bottom: 1px solid transparent !important;
  border-image: linear-gradient(90deg, transparent 0%, rgba(94,234,212,.35) 25%, rgba(139,156,255,.5) 55%, rgba(192,132,252,.35) 80%, transparent 100%) 1 !important;
}
[data-slot="composer-host"] { border-radius: 18px !important; transition: box-shadow .2s ease, border-color .2s ease; }
.dark [data-slot="composer-host"] {
  background: rgba(16,20,27,.72) !important;
  backdrop-filter: blur(18px) saturate(150%);
  box-shadow: 0 0 0 1px rgba(139,156,255,.12), 0 14px 40px rgba(0,0,0,.45) !important;
}
.dark [data-slot="composer-host"]:focus-within {
  box-shadow: 0 0 0 1px rgba(139,156,255,.45), 0 14px 46px rgba(94,234,212,.08), 0 0 60px rgba(139,156,255,.10) !important;
}
:root:not(.dark) [data-slot="composer-host"] { box-shadow: 0 1px 0 rgba(0,0,0,.02), 0 8px 24px rgba(27,30,38,.06) !important; }

/* Messages */
[data-user-message-bubble] { border-radius: 16px 16px 4px 16px !important; }
.dark [data-user-message-bubble] {
  background: linear-gradient(180deg, rgba(31,39,62,.92), rgba(23,29,46,.92)) !important;
  border: 1px solid rgba(139,156,255,.18) !important;
  box-shadow: 0 6px 24px rgba(0,0,0,.25);
  backdrop-filter: blur(8px);
}
.chat-markdown { line-height: 1.68; }
.dark .chat-markdown { text-shadow: 0 1px 14px rgba(8,10,15,.85), 0 0 2px rgba(8,10,15,.6); }
.dark .chat-markdown pre, .dark .chat-markdown-codeblock, .dark .chat-markdown code { text-shadow: none; }
.chat-markdown a { text-underline-offset: 3px; }
.dark .chat-markdown a { color: #a9b5ff !important; text-decoration-color: rgba(139,156,255,.45) !important; }
.dark .chat-markdown a:hover { color: #99f6e4 !important; text-decoration-color: rgba(94,234,212,.6) !important; }
.dark .chat-markdown :not(pre) > code {
  background: rgba(139,156,255,.12) !important;
  color: #c9d0ff !important;
  border: 1px solid rgba(139,156,255,.16) !important;
  border-radius: 6px !important;
  padding: .08em .38em !important;
}
.dark .chat-markdown strong { color: #f1f3f8; }
.chat-markdown blockquote { border-left: 3px solid #8b9cff !important; padding-left: .9em; opacity: .9; }
.dark .chat-markdown hr { border: 0 !important; height: 1px; background: linear-gradient(90deg, transparent, rgba(139,156,255,.4), rgba(94,234,212,.3), transparent) !important; }
.dark .chat-markdown table { background: rgba(12,15,22,.72); backdrop-filter: blur(10px); border-radius: 10px; }
.dark .chat-markdown th { background: rgba(139,156,255,.08) !important; }
.dark .chat-markdown th, .dark .chat-markdown td { border-color: rgba(139,156,255,.12) !important; }

.chat-markdown-codeblock { border-radius: 12px !important; border: 1px solid rgba(139,156,255,.12) !important; }
.dark .chat-markdown-codeblock { background: rgba(10,13,19,.88) !important; box-shadow: 0 8px 28px rgba(0,0,0,.3); backdrop-filter: blur(10px); }
:root:not(.dark) .chat-markdown-codeblock { border-color: #e4e2dc !important; }

/* Sidebar */
.dark [data-slot="sidebar-inner"] {
  background:
    linear-gradient(180deg, rgba(94,234,212,.05) 0%, transparent 18%),
    radial-gradient(420px 320px at 100% 100%, rgba(139,156,255,.08), transparent 70%),
    #0c0f15 !important;
}
[data-thread-item] { border-radius: 10px !important; transition: background-color .15s ease; }
[data-thread-item] [data-sidebar-row] { border-radius: 10px !important; transition: background-color .15s ease; }

/* Selected thread: soft tint, hairline outline, straight gradient pill on the left */
[data-thread-item] [aria-current]:not([aria-current="false"]) { position: relative; }
.dark [data-thread-item] [aria-current]:not([aria-current="false"]) {
  background: linear-gradient(90deg, rgba(139,156,255,.13) 0%, rgba(139,156,255,.05) 65%, rgba(139,156,255,.03) 100%) !important;
  box-shadow: inset 0 0 0 1px rgba(139,156,255,.12) !important;
}
[data-thread-item] [aria-current]:not([aria-current="false"])::after {
  content: "";
  position: absolute; left: 3px; top: 50%; transform: translateY(-50%);
  width: 3px; height: 44%;
  border-radius: 3px;
  background: linear-gradient(180deg, #5eead4, #8b9cff);
  box-shadow: 0 0 10px rgba(139,156,255,.55);
  pointer-events: none;
}
:root:not(.dark) [data-thread-item] [aria-current]:not([aria-current="false"])::after { background: #4f5bd5; box-shadow: none; }

/* Controls and popups */
[data-slot="button"] { border-radius: 10px !important; transition: background-color .15s ease, box-shadow .15s ease, transform .1s ease; }
[data-slot="button"]:active { transform: scale(.97); }
[data-slot="input"], [data-slot="select-trigger"] { border-radius: 10px !important; }
.dark [data-slot="input"]:focus-visible { box-shadow: 0 0 0 3px rgba(139,156,255,.22) !important; }
[data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"] { border-radius: 14px !important; }
.dark [data-slot="dialog-popup"], .dark [data-slot="popover-popup"], .dark [data-slot="menu-popup"] {
  background: rgba(19,24,34,.9) !important;
  backdrop-filter: blur(20px) saturate(150%);
  box-shadow: 0 0 0 1px rgba(139,156,255,.14), 0 24px 60px rgba(0,0,0,.55) !important;
}
.dark [data-slot="tooltip-popup"] { background: #1b2133 !important; color: #e6e9ef !important; border: 1px solid rgba(139,156,255,.18) !important; border-radius: 8px !important; }
.dark [data-thread-terminal-drawer] { border-top: 1px solid rgba(139,156,255,.2) !important; box-shadow: 0 -10px 30px rgba(0,0,0,.35); }

::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(139,156,255,.18); border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: rgba(139,156,255,.34); }
[data-slot="scroll-area-thumb"] { background: rgba(139,156,255,.22) !important; }
